DROP TRIGGER pump_group_broadcast_closure_insert;
--> statement-breakpoint
CREATE TRIGGER pump_group_broadcast_closure_insert BEFORE INSERT ON pump_group_broadcast_closures BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM pump_group_broadcast_observations o JOIN pump_group_broadcast_reviews b ON b.id=o.broadcast_id AND b.owner_id=o.owner_id JOIN pump_launch_reviews r ON r.id=b.review_id AND r.owner_id=b.owner_id JOIN pump_group_observations g ON g.id=json_extract(o.observation,'$.groupObservationId') AND g.owner_id=o.owner_id
 WHERE o.id=NEW.observation_id AND o.review_id=NEW.review_id AND o.owner_id=NEW.owner_id AND r.state='signed' AND r.receipt IS NULL
 AND json_extract(r.signed,'$.signedGroupSha256')=b.signed_group_sha256 AND json_extract(NEW.receipt,'$.format')='pump-launch-group-broadcast-terminal-v1' AND json_extract(NEW.receipt,'$.reviewId')=r.id AND json_extract(NEW.receipt,'$.contextSha256')=b.context_sha256
 AND json_extract(NEW.receipt,'$.broadcastSha256')=b.sha256 AND json_extract(NEW.receipt,'$.signedGroupSha256')=b.signed_group_sha256 AND json_extract(NEW.receipt,'$.observationId')=o.id AND json_extract(NEW.receipt,'$.observationSha256')=o.sha256
 AND (json_extract(NEW.receipt,'$.kind')= CASE NEW.state WHEN 'cancelled' THEN 'expired-unobserved' ELSE NEW.state END OR (json_extract(NEW.receipt,'$.kind')='partial' AND NEW.state IN ('finalized','failed')))
 AND json_extract(NEW.receipt,'$.sourceState')='signed' AND json_extract(NEW.receipt,'$.manifestSha256')=json_extract(r.review,'$.manifestSha256') AND json_extract(NEW.receipt,'$.broadcastId')=b.id AND json_extract(NEW.receipt,'$.observedAt')=o.created_at
 AND json_extract(NEW.receipt,'$.groupNetworkFeeRaw')=json_extract(g.observation,'$.receipt.knownNetworkFeeRaw')
 AND json_extract(NEW.receipt,'$.tipNetworkFeeRaw') IS json_extract(o.observation,'$.tip.networkFeeRaw') AND json_extract(NEW.receipt,'$.tipDebitRaw') IS json_extract(o.observation,'$.tip.tipDebitRaw')
 AND CAST(json_extract(NEW.receipt,'$.knownNetworkFeeRaw') AS INTEGER)=CAST(json_extract(g.observation,'$.receipt.knownNetworkFeeRaw') AS INTEGER)+COALESCE(CAST(json_extract(o.observation,'$.tip.networkFeeRaw') AS INTEGER),0)
 AND json_extract(NEW.receipt,'$.networkFeeUnresolved')= CASE WHEN json_extract(NEW.receipt,'$.kind')='partial' THEN 0 WHEN json_extract(g.observation,'$.receipt.networkFeeUnresolved')=1 OR json_extract(o.observation,'$.tip.networkFeeRaw') IS NULL THEN 1 ELSE 0 END
 AND json_extract(NEW.receipt,'$.reservationsReleased')=1 AND json_extract(NEW.receipt,'$.economicSettlementVerified')=0 AND json_extract(NEW.receipt,'$.completeLaunch')=0 AND json_extract(NEW.receipt,'$.signingAllowed')=0 AND json_extract(NEW.receipt,'$.executionAllowed')=0
 AND julianday('now')-julianday(o.created_at) BETWEEN 0 AND 5.0/86400 AND julianday('now')-julianday(NEW.created_at) BETWEEN 0 AND 5.0/86400
 AND ((NEW.state='finalized' AND json_extract(NEW.receipt,'$.kind')='finalized' AND g.observed_state='complete' AND json_extract(g.observation,'$.receipt.networkFeeUnresolved')=0 AND json_extract(o.observation,'$.state')='finalized' AND json_extract(o.observation,'$.tip.finalized')=1 AND json_extract(o.observation,'$.tip.succeeded')=1 AND json_extract(o.observation,'$.tip.networkFeeRaw') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM json_each(g.observation,'$.receipt.packets') packet WHERE json_extract(packet.value,'$.slot') IS NOT json_extract(o.observation,'$.tip.slot') OR json_extract(packet.value,'$.finalized') IS NOT 1 OR json_extract(packet.value,'$.succeeded') IS NOT 1 OR json_extract(packet.value,'$.networkFeeRaw') IS NULL))
 OR (NEW.state='failed' AND json_extract(NEW.receipt,'$.kind')='failed' AND g.observed_state='failed' AND json_extract(g.observation,'$.receipt.networkFeeUnresolved')=0 AND json_extract(o.observation,'$.state')='failed' AND json_extract(o.observation,'$.tip.finalized')=1 AND json_extract(o.observation,'$.tip.succeeded')=0 AND json_extract(o.observation,'$.tip.networkFeeRaw') IS NOT NULL)
 OR (NEW.state='cancelled' AND g.observed_state='expired-unobserved' AND json_extract(o.observation,'$.state')='expired-unobserved' AND json_extract(g.observation,'$.receipt.observedPacketCount')=0 AND json_extract(g.observation,'$.receipt.expiry.pastExpiryMargin')=1 AND json_extract(g.observation,'$.receipt.expiry.mintAbsent')=1 AND json_extract(g.observation,'$.receipt.expiry.marginBlocks')=32
 AND json_extract(g.observation,'$.receipt.expiry.lastValidBlockHeight')=json_extract(b.review,'$.lastValidBlockHeight')
 AND CAST(json_extract(g.observation,'$.receipt.expiry.finalizedBlockHeight') AS INTEGER)>CAST(json_extract(b.review,'$.lastValidBlockHeight') AS INTEGER)+32
 AND CAST(json_extract(g.observation,'$.receipt.expiry.mintObservedSlot') AS INTEGER)>=CAST(json_extract(g.observation,'$.receipt.expiry.expiryBankSlot') AS INTEGER)
 AND json_extract(o.observation,'$.tip.finalized')=0 AND json_extract(o.observation,'$.tip.slot') IS NULL))
 OR (json_extract(NEW.receipt,'$.kind')='partial' AND json_extract(o.observation,'$.state')='partial-final' AND g.observed_state IN ('complete','failed','partial','expired-unobserved')
 AND json_extract(NEW.receipt,'$.packetCount')=json_array_length(g.observation,'$.receipt.packets') AND json_extract(NEW.receipt,'$.packetCount')=json_array_length(r.signed,'$.packets')
 AND json_extract(NEW.receipt,'$.landedPacketCount')=json_extract(g.observation,'$.receipt.observedPacketCount') AND json_extract(NEW.receipt,'$.succeededPacketCount')=json_extract(g.observation,'$.receipt.successfulPacketCount')
 AND (SELECT count(*) FROM json_each(g.observation,'$.receipt.packets') packet WHERE json_extract(packet.value,'$.finalized')=1)=json_extract(g.observation,'$.receipt.observedPacketCount')
 AND (SELECT count(*) FROM json_each(g.observation,'$.receipt.packets') packet WHERE json_extract(packet.value,'$.succeeded')=1)=json_extract(g.observation,'$.receipt.successfulPacketCount')
 AND NEW.state= CASE WHEN json_extract(g.observation,'$.receipt.successfulPacketCount')=json_array_length(g.observation,'$.receipt.packets') THEN 'finalized' ELSE 'failed' END
 AND NOT EXISTS(SELECT 1 FROM json_each(g.observation,'$.receipt.packets') packet WHERE json_extract(packet.value,'$.finalized')=1 AND json_extract(packet.value,'$.networkFeeRaw') IS NULL)
 AND (CAST(json_extract(g.observation,'$.receipt.observedPacketCount') AS INTEGER)>=1 OR (g.observed_state='expired-unobserved' AND json_extract(g.observation,'$.receipt.expiry.mintAbsent')=1 AND CAST(json_extract(g.observation,'$.receipt.expiry.mintObservedSlot') AS INTEGER)>=CAST(json_extract(g.observation,'$.receipt.expiry.expiryBankSlot') AS INTEGER) AND json_extract(o.observation,'$.tip.finalized')=1))
 AND (json_extract(g.observation,'$.receipt.observedPacketCount')=json_array_length(g.observation,'$.receipt.packets') OR (json_extract(g.observation,'$.receipt.expiry.pastExpiryMargin')=1 AND json_extract(g.observation,'$.receipt.expiry.marginBlocks')=32
 AND json_extract(g.observation,'$.receipt.expiry.lastValidBlockHeight')=json_extract(b.review,'$.lastValidBlockHeight') AND CAST(json_extract(g.observation,'$.receipt.expiry.finalizedBlockHeight') AS INTEGER)>CAST(json_extract(b.review,'$.lastValidBlockHeight') AS INTEGER)+32))
 AND (json_extract(o.observation,'$.tip.finalized')=1 OR (json_extract(o.observation,'$.expiry.pastExpiryMargin')=1 AND json_extract(o.observation,'$.expiry.marginBlocks')=32
 AND json_extract(o.observation,'$.expiry.lastValidBlockHeight')=json_extract(b.review,'$.lastValidBlockHeight') AND CAST(json_extract(o.observation,'$.expiry.finalizedBlockHeight') AS INTEGER)>CAST(json_extract(b.review,'$.lastValidBlockHeight') AS INTEGER)+32))))
 THEN RAISE(ABORT,'Exact finalized, expired or settled partial group and tip proof required') END;
END;
